105	
106	// ── Shell selection — the one place the ops2 rollout is flipped ─────────────
107	//
108	// ┌─ WHERE THE DOCUMENTS ARE ────────────────────────────────────────────────┐
109	// │ Both sources below live ONLY on the `design/ops2-planning` branch today:  │
110	// │   docs/adr/0002-ops2-path-routing-not-hash.md   (cited here as "the       │
111	// │     routing ADR" — read it with `git show design/ops2-planning:<path>`)   │
112	// │   docs/specs/ops2.md §9, §12                                             │
113	// │                                                                          │
114	// │ Do NOT read this branch's docs/adr/0002-*.md as the routing decision: on  │
115	// │ this branch and on main, 0002 is                                         │
116	// │ `0002-trade-status-derived-from-application-ledger.md`, an unrelated ADR. │
117	// │ The two branches have colliding ADR numbers (0001 as well as 0002); the   │
118	// │ renumbering is the planning thread's to make. Until it does, the filename │
119	// │ is the citation and the number is not.                                    │
120	// └──────────────────────────────────────────────────────────────────────────┘
121	//
122	// The successor to `isOps ? "/ops.html" : "/index.html"`. The spec's §12 gives
123	// it three states, and each flip is a one-line, versions-revertible deploy
124	// (routing ADR) — `wrangler versions upload` for a preview that does not move
125	// production traffic, then `wrangler versions deploy` to promote:
126	//
127	//   1. BUILD (live now) — legacy at the ops root, ops2 reachable at /ops2.
128	//      Nobody's daily work moves.
129	//   2. SWITCH-OVER — ops2 at the root, legacy at /legacy: the fire escape,
130	//      unadvertised, used only if ops2 fails at something.
131	//   3. DELETION — legacy gone from the bundle, with its Vite entry and the
132	//      domain-based identity path.
133	//
134	// States 2 and 3 are written out as comments below, not implemented, and are
135	// deliberately one edit each. Switch-over and deletion are two events, two
136	// commits, two deploys, separated by a soak.
137	//
138	// AUTHENTICATION IS NOT INVOLVED. ops2 lives on the ops HOST, so Cloudflare
139	// Access protects it at the edge exactly as it protects the legacy console,
140	// and `isOps` still decides host-level behaviour on its own. That is the whole
141	// reason ops2 took a path prefix instead of a hostname (the spec's §9): a second
142	// hostname would need a second Access audience and a widened `isOps`, which is
143	// a security-path change for a cosmetic reason.
144	type Shell = "/index.html" | "/ops.html" | "/ops2.html";
145	
146	export function opsShellFor(isOps: boolean, pathname: string): Shell {
147	  if (!isOps) return "/index.html";                       // the customer site, unchanged
148	
149	  // ── State 1: BUILD ────────────────────────────────────────────────────────
150	  return isUnderOps2(pathname) ? "/ops2.html" : "/ops.html";
151	
152	  // ── State 2: SWITCH-OVER ──────────────────────────────────────────────────
153	  // return pathname === "/legacy" || pathname.startsWith("/legacy/")
154	  //   ? "/ops.html" : "/ops2.html";
155	
156	  // ── State 3: DELETION ─────────────────────────────────────────────────────
157	  // return "/ops2.html";
158	}
159	
160	// Route a request to its response. Every `return` below is a page or a payload;
161	// the security policy is attached once, by the fetch handler that wraps this.
162	// There are nine exits here — two redirects, sitemap, robots, static assets, the
163	// API, the ops2 shell, the ops shell, the customer shell and the shell-render
164	// fallback — and before the wrapper existed, every one of them answered with no
165	// policy at all. Adding an exit means adding it to that wrapper's blast radius,
166	// which is why the count is written down: an exit nobody counted is an exit
167	// nobody checked.
168	async function route(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
169	    const url = new URL(request.url);
170	
171	    // ── ONE HOST PER SITE ───────────────────────────────────────────────────
172	    // www.* is a DNS alias of the apex, so it served the whole site a second
173	    // time — with its own sitemap and its own self-referencing canonicals, i.e.
174	    // a complete duplicate under a second canonical host. It also broke the
175	    // page silently: Sanity's CORS list allows the apex, and an Origin of
176	    // www.<domain> is a different origin, so every browser-side query failed
177	    // and the header lost its logo.
178	    //
179	    // A CNAME cannot fix that — DNS does not change the URL the browser holds,
180	    // and the Origin header is built from that URL. Only a redirect does.
181	    //
182	    // Narrow, for the same reasons as the slash rule below: GET/HEAD only, and
183	    // only the www. prefix — ops.* is a real, separate application.
184	    const host = request.headers.get("host") ?? url.hostname;
185	    if ((request.method === "GET" || request.method === "HEAD") && host.startsWith("www.")) {
186	      const target = new URL(url);
187	      target.hostname = url.hostname.replace(/^www\./, "");
188	      return Response.redirect(target.toString(), 301);
189	    }
190	
191	    // ── ONE URL PER PAGE ────────────────────────────────────────────────────
192	    // routeFromPathname() strips trailing slashes before matching, which is kind
193	    // to a visitor who types one but meant that /products and /products/ BOTH
194	    // returned 200 with identical content — two URLs for one page, which is what
195	    // Search Console reports as "duplicate without user-selected canonical".
196	    // The no-slash form wins: it is what the sitemap lists and what pathForPage()
197	    // generates, so redirecting the other way would fight every internal link.
198	    //
199	    // Deliberately narrow:
200	    //  • "/" is exempt — the root's slash is not a trailing slash.
201	    //  • GET/HEAD only. A 301 on a POST invites the client to re-issue it as GET
202	    //    and silently drop the body; /api/* is excluded outright for the same
203	    //    reason, and its 404 handler is a better answer than a redirect anyway.
204	    //  • search is carried over, so /products/?family=awning keeps its query.
205	    // Placed first so nothing downstream can answer 200 before it runs.
206	    const method = request.method;
207	    if ((method === "GET" || method === "HEAD") &&
208	        url.pathname.length > 1 && url.pathname.endsWith("/") &&
209	        !url.pathname.startsWith("/api/")) {
210	      const target = new URL(url);
211	      target.pathname = url.pathname.replace(/\/+$/, "");
212	      return Response.redirect(target.toString(), 301);
213	    }
214	
215	    // Real static assets (hashed js/css/img, etc.) are served directly, and never
216	    // wait on the catalogue. Anything else is a client-side route → serve the
217	    // host's SPA shell. The ops console is a separate bundle on ops.* (guarded by
218	    // Cloudflare Access in prod); we pick the shell up front because the asset
219	    // system maps "/" to index.html.
220	    // Crawler-facing files are GENERATED, not static, so they must be handled
221	    // before the asset check — both end in an extension and would otherwise be
222	    // looked up in the bundle and 404.
223	    // ── /r/<CODE> — the referral link ───────────────────────────────────────
224	    // Sits here, ahead of the asset check and the SPA shell, because it is a
225	    // worker-level redirect rather than a client route: the cookie has to be set
226	    // by the server, and a code containing a dot would otherwise look like an
227	    // asset.
228	    //
229	    // It redirects identically whatever the code is. Recording happens later, at
230	    // signup, and only for an account that did not already exist (AC-7) — so a
231	    // stranger clicking a link, or inventing one, cannot learn anything from the
232	    // response and cannot cause anything to be written.
233	    const referralLink = /^\/r\/([A-Za-z2-9]{3}-[A-Za-z2-9]{3})$/.exec(url.pathname);
234	    if (referralLink && (request.method === "GET" || request.method === "HEAD")) {
235	      const code = referralLink[1].toUpperCase();
236	      const known = await env.DB
237	        .prepare("SELECT 1 AS ok FROM user WHERE referral_code = ?")
238	        .bind(code)
239	        .first<{ ok: number }>();
240	      const headers = new Headers({ Location: "/refer" });
241	      // ONE PER MEMBER, and they get pasted into WhatsApp, Facebook groups and
242	      // forums — precisely where crawlers harvest links. A 302's source URL is
243	      // usually not indexed, but "usually" is not a control.
244	      //
245	      // Deliberately NOT disallowed in robots.txt: a disallow prevents crawling,
246	      // so this header would never be fetched, and a widely-shared blocked URL can
247	      // still land in the index with no content at all. A directive has to be seen
248	      // to be obeyed.
249	      headers.set("X-Robots-Tag", "noindex");
250	      if (known) {
251	        const attrs = [`of_ref=${code}`, "Path=/", "HttpOnly", "SameSite=Lax", "Max-Age=7776000"];
252	        if (env.APP_ENV === "production") attrs.push("Secure");
253	        headers.set("Set-Cookie", attrs.join("; "));
254	      }
255	      return new Response(null, { status: 302, headers });
256	    }
257	
258	    const isOps = host.startsWith("ops.");
259	    if (!isOps && url.pathname === "/sitemap.xml") {
260	      await ensureCatalogue(env);           // products come from the live catalogue
261	      return buildSitemap(env, url.origin);
262	    }
263	    if (!isOps && url.pathname === "/robots.txt") return buildRobots(url.origin, env.APP_ENV === "production");
264	
265	    // An /api/ path is never a file in the bundle. Without that exclusion any API
266	    // route whose last segment carries an extension — the payout CSV export, and
267	    // anything like it later — is looked up as a static asset and 404s before it
268	    // reaches a handler, which reads as "the route isn't registered" and is not.
269	    const isAsset = !url.pathname.startsWith("/api/")
270	      && /\.[a-zA-Z0-9]+$/.test(url.pathname) && !url.pathname.endsWith(".html");
271	    if (isAsset) return env.ASSETS.fetch(request);
272	
273	    // The liveness probe must stay cheap — it also never waits on Sanity.
274	    if (url.pathname === "/api/health") return api.fetch(request, env, ctx);
275	
276	    // The shell is chosen here, before hydration, because ONE of them needs to
277	    // be served before it: ops2 reads no catalogue.
278	    //
279	    // Everything else below stays behind ensureCatalogue and must: the API
280	    // serves live catalogue content, and the legacy console reads it too. Only
281	    // the ops2 exit moves in front, and it is the ops2 exit — not `isOps` —
282	    // that is tested, so switch-over and deletion carry it automatically.
283	    //
284	    // Why it matters more than a cold-start milliseconds argument: a failed
285	    // load is deliberately not cached (worker/lib/catalogue.ts), so while Sanity
286	    // is slow or down EVERY request pays the 3s timeout. Behind hydration, the
287	    // one screen whose job is to show that routing and Access work would be the
288	    // screen that looks broken during a CMS outage — which is exactly the
289	    // dependency src/ops2/main.tsx refuses on the client side.
290	    const shell = opsShellFor(isOps, url.pathname);
291	    if (shell === "/ops2.html") return env.ASSETS.fetch(new URL(shell, url.origin).toString());
292	
293	    // Load the catalogue from Sanity once per isolate (no-op unless configured),
294	    // so pricing + snapshots use live content. Cheap after the first request, and
295	    // time-bounded so a slow CMS can't stall the response (see ensureCatalogue).
296	    await ensureCatalogue(env);
297	
298	    if (url.pathname.startsWith("/api/")) {
299	      return api.fetch(request, env, ctx);
300	    }
301	
302	    const res = await env.ASSETS.fetch(new URL(shell, url.origin).toString());
303	
304	    // Rewrite the customer shell's <head> for this URL. The SPA injects its own
305	    // tags after hydration, but social scrapers read the first response and never
306	    // run JS — so without this, every shared link previews as the build-time
307	    // placeholder. Failure here must never cost the page: fall back to the shell.
308	    if (isOps) return res;
309	    try {
310	      // The status comes back with the head because both are decided from one
311	      // route resolution. An unknown path, an unknown product or post slug, and a
312	      // product withdrawn from sale all serve the SPA shell — the client renders
313	      // its 404 page — but with a 404 STATUS. Serving that page behind a 200 is a
314	      // soft 404: the URL stays indexable and every mistyped address becomes a
315	      // duplicate of whatever it landed on.
316	      const { html, status } = await renderShell(env, await res.text(), url);
317	      return new Response(html, { status, headers: res.headers });
318	    } catch (e) {
319	      console.log(`[shell] head render failed: ${String(e)}`);
320	      return env.ASSETS.fetch(new URL(shell, url.origin).toString());
321	    }
322	}
323	
324	export default {
325	  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
326	    const url = new URL(request.url);
327	    const host = request.headers.get("host") ?? url.hostname;
328	    return applySecurity(await route(request, env, ctx), securityOptions(env, url, host));
329	  },
330	  async queue(batch: MessageBatch<AiExtractionJob>, env: Env): Promise<void> {
331	    await consumeAiJobs(batch, env);
332	  },
333	  async scheduled(_event: ScheduledController, env: Env): Promise<void> {
334	    await drainLearningOutbox(env, 50);
335	    // Sweep for pricing gaps, so a missed publish webhook cannot hide one
336	    // indefinitely. Caught separately: neither job may sink the other.
337	    await reconcilePricing(env).catch((e) => console.log(`[reconcile] scheduled sweep failed: ${String(e)}`));
338	    // Release referral money held because its referrer was briefly unpayable.
339	    // Caught separately like its peers: a referral sweep must not sink pricing
340	    // reconciliation, and vice versa.
341	    await referralSweep(env).catch((e) => console.log(`[referral] scheduled sweep failed: ${String(e)}`));
342	    // Release AI jobs whose worker died mid-run; without this a customer sits
343	    // on "reading your documents" until they clear their own project.
344	    await reapAbandonedAiJobs(env)
345	      .then((n) => { if (n.claims || n.runs) console.log(`[ai] reaped ${n.claims} claim(s), ${n.runs} run(s)`); })
346	      .catch((e) => console.log(`[ai] reaper failed: ${String(e)}`));
347	  },
348	};
