13	// Seed identities are read from the seed itself so local fixture edits (extra
14	// test users, different sign-in addresses) don't break the suite.
15	const seedSql = readFileSync(join(projectRoot, "scripts", "db", "seed.sql"), "utf8");
16	const seedUserRows = [...seedSql.matchAll(/\(\s*'(u_[\w]+)'\s*,\s*'([^']+)'/g)];
