77	export async function stop(processHandle) {
78	  const child = processHandle?.child;
79	  if (!child?.pid || child.exitCode !== null) return;
80	  const exited = new Promise((resolveExit) => child.once("exit", resolveExit));
81	  if (process.platform === "win32") {
82	    const killedTree = await run("taskkill", ["/PID", String(child.pid), "/T", "/F"])
