106	export async function waitForUrl(url, processHandle, timeoutMs = 30_000) {
107	  const deadline = Date.now() + timeoutMs;
108	  let lastError;
109	  while (Date.now() < deadline) {
110	    if (processHandle.child.exitCode !== null) {
111	      throw new Error(`Wrangler exited before becoming ready.\n${processHandle.output()}`);
112	    }
113	    try {
114	      const response = await fetch(url);
