1	// Cloudflare bindings available to the Worker. Declared in wrangler.jsonc.
2	export interface Env {
3	  /** D1 — transactional domain model (see migrations/). */
4	  DB: D1Database;
5	  /** R2 — file bytes (plans, schedules, generated PDFs). */
6	  FILES: R2Bucket;
7	  /** KV — ephemeral auth state: OTP codes + session tokens (TTL-managed). */
8	  KV: KVNamespace;
9	  /** Static assets binding — serves the built Vite SPA (./dist). */
10	  ASSETS: Fetcher;
11	  /** 'development' | 'production' — from vars. */
12	  APP_ENV: string;
13	  /** Comma-separated email domains allowed to sign in to the ops console. */
14	  STAFF_EMAIL_DOMAINS?: string;
15	  /** Cloudflare Access (prod staff auth) — team domain + application AUD. */
16	  ACCESS_TEAM_DOMAIN?: string;
17	  ACCESS_AUD?: string;
18	  /** Resend email — API key (secret) + verified From address (var). */
19	  RESEND_API_KEY?: string;
20	  EMAIL_FROM?: string;
21	  /** Contact form: where enquiries are emailed (falls back to EMAIL_FROM). */
22	  CONTACT_TO?: string;
23	  /** Enquiries: internal OpenFrame queue address (falls back to CONTACT_TO/EMAIL_FROM). */
24	  ENQUIRY_INTERNAL_TO?: string;
25	  /** Enquiries: single manufacturer handoff address for ALL locations (appointments). */
26	  MANUFACTURER_TO?: string;
27	  /** Comma-separated domains whose users are manufacturer partners (Enquiries only). */
28	  MANUFACTURER_EMAIL_DOMAINS?: string;
29	  /** Cloudflare Turnstile secret (captcha) — set to enable server verification. */
30	  TURNSTILE_SECRET?: string;
31	  /** Sanity catalogue source (Worker-side). Client uses VITE_SANITY_* instead. */
32	  SANITY_PROJECT_ID?: string;
33	  SANITY_DATASET?: string;
34	  /** Workers AI (schedule extraction accuracy tier). Optional — deterministic
35	   *  on-stack extraction runs without it. Bound in wrangler.jsonc as "AI". */
36	  AI?: unknown;
37	  /** Durable registered-user AI extraction jobs. Anonymous requests never write
38	   * to this queue. Optional only for local tests/development. */
39	  AI_JOBS?: Queue<{ projectId: string; generation: number; debounceToken: string }>;
40	  /** Extraction engine selector: 'deterministic' (default/on-stack), 'ai'
41	   *  (force Workers AI), or 'auto' (deterministic, escalate to AI when weak). */
42	  PARSE_ENGINE?: string;
